solution.solution.cpp:
#include <string>

inline std::string g_log{};

class Base
{
public:
    Base() { g_log += "+Base "; }
    ~Base() { g_log += "-Base "; }
};

class Derived : public Base
{
public:
    Derived() { g_log += "+Derived "; }
    ~Derived() { g_log += "-Derived "; }
};

unitTests:
static_assert(std::is_base_of_v<Base, Derived>);
TEST("construction goes down, destruction comes back up") { g_log.clear(); { Derived d{}; } CHECK_EQ(g_log, "+Base +Derived -Derived -Base "); }
TEST("a plain Base logs only itself") { g_log.clear(); { Base b{}; } CHECK_EQ(g_log, "+Base -Base "); }

